/**
 * How wide each column of slots is.
 *
 * The grid divides the row evenly on its own; this is what the operator gets to say instead.
 * It arrived on 2026-09-23 for the two-slot case — one handle, one number — and the operator
 * asked for the same thing with three or more the same day. So the number became a row of
 * numbers, one per column, always adding up to one.
 *
 * Widths are kept per column count rather than as a single row. Going from three columns to
 * two and back must not throw away what was set for three, and the two shapes have nothing to
 * say to each other: there is no sensible way to read a row of three as a row of two.
 */

export const MIN_COLUMNS_FOR_HANDLE = 2;

/** The old two-column floor, needed only to read v0.17's saved single-number split. */
export const LEGACY_SPLIT_FLOOR = 0.2;
/** Reject a stored width too tiny to be a meaningful column on any screen. */
export const STORED_MIN_SHARE = 0.01;

/** Close enough to the same width. Fractions come back from storage slightly rounded. */
const TOLERANCE = 1e-6;

/** Two icons' worth of pixels as a share of the available column space. */
export function minShare(columns: number, contentPx: number, minSlotPx: number): number {
  const count = Math.max(1, columns);
  if (!Number.isFinite(contentPx) || contentPx <= 0) return 1 / count;
  return Math.min(1 / count, Math.max(0, minSlotPx) / contentPx);
}

export function evenWidths(columns: number): number[] {
  const count = Math.max(1, Math.round(columns));
  return Array.from({ length: count }, () => 1 / count);
}

/**
 * Reads a stored row. Never throws: storage is the operator's own file and an older version
 * wrote a different shape. Anything that is not a usable row of exactly `columns` widths comes
 * back as `null`, and the caller falls back to even.
 *
 * A row that adds up to something other than one is scaled rather than rejected — rounding on
 * the way through storage is not a reason to throw the operator's layout away.
 */
export function readWidths(value: unknown, columns: number): number[] | null {
  if (!Array.isArray(value) || value.length !== columns || columns < 1) return null;

  const raw: number[] = [];
  for (const entry of value) {
    if (typeof entry !== 'number' || !Number.isFinite(entry) || entry <= 0) return null;
    raw.push(entry);
  }

  const total = raw.reduce((sum, entry) => sum + entry, 0);
  if (total <= 0) return null;

  const scaled = raw.map((entry) => entry / total);
  // A pixel floor depends on the current screen; a row saved on a wider one is still valid.
  if (scaled.some((entry) => entry < STORED_MIN_SHARE - TOLERANCE)) return null;
  return scaled;
}

/**
 * Moving one handle.
 *
 * `boundary` is which gap is being dragged: gap 0 sits between the first and second columns.
 * Only those two columns change — every other column keeps the width it had, so pulling one
 * handle never disturbs a handle the operator set earlier.
 *
 * `delta` is a share of the whole row, and is trimmed so neither of the two can fall through
 * the floor. Trimming rather than refusing is what lets a finger run past the end and come
 * back: the answer tracks the finger the whole way instead of letting go at the limit.
 */
export function dragWidths(
  widths: readonly number[],
  boundary: number,
  delta: number,
  floor: number,
): number[] {
  const next = [...widths];
  if (
    next[boundary] === undefined ||
    next[boundary + 1] === undefined ||
    !Number.isFinite(delta) ||
    !Number.isFinite(floor) ||
    floor < 0 ||
    floor * widths.length > 1
  )
    return next;

  // A row saved on a wider display may already be below this display's pixel floor. Give
  // that column room first, taking only the spare width from the others.
  const deficit = next.reduce((sum, share) => sum + Math.max(0, floor - share), 0);
  if (deficit > 0) {
    const spare = next.reduce((sum, share) => sum + Math.max(0, share - floor), 0);
    next.forEach((share, index) => {
      next[index] = share < floor ? floor : share - (deficit * (share - floor)) / spare;
    });
  }

  const before = next[boundary] as number;
  const after = next[boundary + 1] as number;
  const move = Math.min(Math.max(delta, floor - before), after - floor);
  next[boundary] = before + move;
  next[boundary + 1] = after - move;
  return next;
}

/** Whether this row is the one the grid would have drawn by itself. */
export function isEven(widths: readonly number[]): boolean {
  const even = 1 / widths.length;
  return widths.every((entry) => Math.abs(entry - even) < TOLERANCE);
}
