/**
 * Numbers and dates as the screen writes them. Pure, so the odd cases can be pinned by tests.
 */

/**
 * Seconds as a clock reads them. An hour-long video gets its hours; a short does not, because
 * a leading `0:` on every line is three characters that never say anything.
 */
export function clock(seconds: number): string {
  const whole = Number.isFinite(seconds) ? Math.max(0, Math.floor(seconds)) : 0;
  const s = String(whole % 60).padStart(2, '0');
  const m = Math.floor(whole / 60) % 60;
  const h = Math.floor(whole / 3600);
  return h > 0 ? `${h}:${String(m).padStart(2, '0')}:${s}` : `${m}:${s}`;
}

const RECENT_UPLOAD_LABEL = 'たった今';
const UPLOAD_AGE_UNITS = [
  { seconds: 365 * 86400, name: '年前' },
  { seconds: 30 * 86400, name: 'か月前' },
  { seconds: 7 * 86400, name: '週間前' },
  { seconds: 86400, name: '日前' },
  { seconds: 3600, name: '時間前' },
  { seconds: 60, name: '分前' },
] as const;

/** The upload age shown beside a video, with larger units for older videos. */
export function uploadAge(iso: string | null | undefined, nowMs = Date.now()): string {
  if (typeof iso !== 'string' || iso === '') return '';
  const date = new Date(iso);
  if (Number.isNaN(date.getTime()) || !Number.isFinite(nowMs)) return '';
  const age = Math.max(0, nowMs - date.getTime()) / 1000;
  if (age < 60) return RECENT_UPLOAD_LABEL;
  const unit = UPLOAD_AGE_UNITS.find(({ seconds }) => age >= seconds);
  return unit === undefined ? RECENT_UPLOAD_LABEL : `${Math.floor(age / unit.seconds)}${unit.name}`;
}
