/**
 * One playback slot: an official player plus the settings the app keeps for it.
 *
 * Two of these run side by side and both stay audible — that is the whole product
 * (ADR-0001). Nothing here coordinates the two; a slot never mutes or pauses its neighbour,
 * because the pair being independent is exactly what the user asked for.
 */

import { NORMAL_SPEED, clampSpeed } from '../core/speed.js';
import { clampVolume } from '../core/volume.js';
import { loadIframeApi } from './api.js';
import { PLAYER_STATE, type PlayerOptions, type YouTubePlayer } from './types.js';

export type SlotStatus = 'loading' | 'empty' | 'ready' | 'playing' | 'paused' | 'ended' | 'error';

export interface SlotCallbacks {
  readonly onStatusChange: (status: SlotStatus) => void;
  /**
   * The API's raw numeric reason for a refusal, passed through without interpretation.
   * Guessing at what the player meant, instead of reading what it said, cost a full day
   * of wrong conclusions on 2026-09-13. The number goes on screen.
   */
  readonly onError: (code: number) => void;
}

function statusFromCode(code: number): SlotStatus {
  switch (code) {
    case PLAYER_STATE.playing:
      return 'playing';
    case PLAYER_STATE.paused:
      return 'paused';
    case PLAYER_STATE.ended:
      return 'ended';
    case PLAYER_STATE.buffering:
      return 'loading';
    case PLAYER_STATE.cued:
    case PLAYER_STATE.unstarted:
      return 'ready';
    default:
      return 'ready';
  }
}

export interface SlotInitial {
  readonly volume: number;
  readonly speed: number;
  readonly loop: boolean;
}

export class Slot {
  private player: YouTubePlayer | null = null;
  private volume: number;
  private speed: number;
  private looping: boolean;
  private muted = false;
  private pendingVideoId: string | null = null;
  private captions = false;
  /** Which video the captions module was last loaded for; it does not carry to the next. */
  private captionsFor: string | null = null;
  /** Which video captions were last switched off for, so each video is only told once. */
  private captionsOffFor: string | null = null;
  /** Bumped on every switch, so a slow track lookup cannot act on a switch since undone. */
  private captionTries = 0;

  constructor(
    private readonly mount: HTMLElement,
    initial: SlotInitial,
    private readonly callbacks: SlotCallbacks,
  ) {
    this.volume = clampVolume(initial.volume);
    this.speed = clampSpeed(initial.speed);
    this.looping = initial.loop;
  }

  /** Build the player. Resolves once YouTube reports it is ready to take commands. */
  async start(initialVideoId: string | null): Promise<void> {
    const namespace = await loadIframeApi();

    await new Promise<void>((resolve) => {
      const options: PlayerOptions = {
        host: 'https://www.youtube.com',
        playerVars: {
          playsinline: 1,
          enablejsapi: 1,
          rel: 0,
          /*
           * No full-screen button of YouTube's own.
           *
           * There were two doors to full screen and they led to different rooms: ours (⛶)
           * puts the slot over the page and keeps our gesture sheet, while YouTube's handed
           * the whole picture back to YouTube's player, controls and all. The operator hit
           * the difference on 2026-09-22 — "枠の画面だとブラウザでの操作感になる". One door now.
           */
          fs: 0,
          origin: window.location.origin,
          cc_lang_pref: 'ja',
          /*
           * Captions start off (operator, 2026-09-30: 字幕はデフォルトオフ). This alone is not
           * enough — YouTube remembers a viewer who once turned captions on and shows them in
           * every embed — so each new video is also told to drop them once it plays.
           */
          cc_load_policy: 0,
        },
        events: {
          onReady: (event) => {
            this.player = event.target;
            this.player.setVolume(this.volume);
            // A slot muted before YouTube answered (every silent slot is) stays muted.
            if (this.muted) this.player.mute();
            if (this.speed !== NORMAL_SPEED) this.player.setPlaybackRate(this.speed);
            if (this.pendingVideoId !== null) this.player.cueVideoById(this.pendingVideoId);
            this.callbacks.onStatusChange(this.pendingVideoId === null ? 'empty' : 'ready');
            resolve();
          },
          onStateChange: (event) => {
            // Looping is the default: a slot that falls silent at the end of its video stops
            // being a slot, and with twenty of them nobody is watching for the one that ended.
            if (event.data === PLAYER_STATE.ended && this.looping) {
              event.target.seekTo(0, true);
              event.target.playVideo();
              return;
            }
            // The captions module is per video: a new video starts without it, so a slot with
            // captions on has to ask again once the new video is actually playing.
            if (event.data === PLAYER_STATE.playing && this.captions) {
              if (this.captionsFor !== this.pendingVideoId) this.applyCaptions();
            }
            // Off is also per video: YouTube's own remembered preference comes back with each
            // one, so a slot with captions off drops them once for every new video.
            if (event.data === PLAYER_STATE.playing && !this.captions) {
              if (this.captionsOffFor !== this.pendingVideoId) {
                this.captionsOffFor = this.pendingVideoId;
                try {
                  event.target.unloadModule('captions');
                } catch {
                  // A player without the module has no captions to drop.
                }
              }
            }
            // YouTube can reset playback rate when it starts a different video. Restore the
            // slot's chosen rate after the new video actually begins.
            if (
              event.data === PLAYER_STATE.playing &&
              event.target.getPlaybackRate() !== this.speed
            ) {
              event.target.setPlaybackRate(this.speed);
            }
            const status = statusFromCode(event.data);
            /*
             * An emptied slot must stay empty on screen. Stopping the video makes the player
             * report `cued` a moment later, which would otherwise read as 準備完了 — and a slot
             * that says it is ready to play, with nothing in it, puts a tap-to-start cover
             * over a black frame.
             */
            this.callbacks.onStatusChange(
              this.pendingVideoId === null && status === 'ready' ? 'empty' : status,
            );
          },
          onError: (event) => {
            this.callbacks.onError(event.data);
            this.callbacks.onStatusChange('error');
          },
        },
        ...(initialVideoId === null ? {} : { videoId: initialVideoId }),
      };
      this.pendingVideoId = initialVideoId;
      new namespace.Player(this.mount, options);
    });
  }

  get videoId(): string | null {
    return this.pendingVideoId;
  }

  /** Load without playing. The user starts playback themselves, by design. */
  cue(videoId: string): void {
    this.pendingVideoId = videoId;
    this.player?.cueVideoById(videoId);
  }

  /**
   * A result chosen by a tap starts as part of that same tap. `startSeconds` carries a video
   * across a swap without sending it back to the beginning.
   */
  loadAndPlay(videoId: string, startSeconds = 0): void {
    this.pendingVideoId = videoId;
    if (startSeconds > 0) this.player?.loadVideoById(videoId, startSeconds);
    else this.player?.loadVideoById(videoId);
  }

  /** Empties the slot: the video stops, is forgotten, and the frame goes back to black. */
  clear(): void {
    this.pendingVideoId = null;
    this.player?.stopVideo();
    this.callbacks.onStatusChange('empty');
  }

  play(): void {
    this.player?.playVideo();
  }

  isPlaying(): boolean {
    return this.player?.getPlayerState() === PLAYER_STATE.playing;
  }

  pause(): void {
    this.player?.pauseVideo();
  }

  setVolume(value: number): number {
    this.volume = clampVolume(value);
    this.player?.setVolume(this.volume);
    return this.volume;
  }

  getVolume(): number {
    return this.volume;
  }

  /** Returns the rate that was actually applied, which may be a snapped one. */
  setSpeed(value: number): number {
    this.speed = clampSpeed(value);
    this.player?.setPlaybackRate(this.speed);
    return this.speed;
  }

  getSpeed(): number {
    return this.speed;
  }

  setLooping(looping: boolean): void {
    this.looping = looping;
  }

  isLooping(): boolean {
    return this.looping;
  }

  /** Moves by `seconds`, forwards or back, staying inside the video. */
  nudge(seconds: number): void {
    const player = this.player;
    if (player === null) return;
    const target = Math.max(0, player.getCurrentTime() + seconds);
    const duration = player.getDuration();
    // A duration of 0 means the player does not know yet; seeking to the end would be worse
    // than seeking a little too far, which the player clamps for us.
    player.seekTo(duration > 0 ? Math.min(target, duration) : target, true);
  }

  /** Where the video is now, in seconds. 0 before the player can answer. */
  position(): number {
    const seconds = this.player?.getCurrentTime() ?? 0;
    return Number.isFinite(seconds) && seconds > 0 ? seconds : 0;
  }

  /**
   * How long the video is, in seconds. 0 while the player does not know yet — and that is a
   * real state, not an error: a cued video has no duration until it has been reached for.
   */
  length(): number {
    const seconds = this.player?.getDuration() ?? 0;
    return Number.isFinite(seconds) && seconds > 0 ? seconds : 0;
  }

  /** Jumps to a point in the video, staying inside it. */
  seek(seconds: number): void {
    const player = this.player;
    if (player === null || !Number.isFinite(seconds)) return;
    const duration = player.getDuration();
    const target = Math.max(0, duration > 0 ? Math.min(seconds, duration) : seconds);
    player.seekTo(target, true);
  }

  /**
   * Captions on or off (operator, 2026-09-24). Returns what the slot now wants; whether the
   * video actually has captions is YouTube's to say, and one without them simply shows none.
   */
  setCaptions(on: boolean): boolean {
    this.captions = on;
    this.applyCaptions();
    return on;
  }

  hasCaptions(): boolean {
    return this.captions;
  }

  private applyCaptions(): void {
    const player = this.player;
    if (player === null) return;
    this.captionTries += 1;
    const attempt = this.captionTries;
    try {
      if (!this.captions) {
        this.captionsFor = null;
        this.captionsOffFor = this.pendingVideoId;
        player.unloadModule('captions');
        return;
      }
      // Before playback starts the module has nothing to attach to; leaving this unset makes
      // the next move to `playing` load it again.
      this.captionsFor =
        player.getPlayerState() === PLAYER_STATE.playing ? this.pendingVideoId : null;
      player.loadModule('captions');
    } catch {
      return;
    }
    // The track list only arrives a moment after the module loads. Japanese if there is one,
    // otherwise the first track — which is usually the video's own language.
    const pick = (left: number): void => {
      if (attempt !== this.captionTries || !this.captions) return;
      try {
        const list = player.getOption('captions', 'tracklist');
        if (Array.isArray(list) && list.length > 0) {
          const codes = list
            .map((track: unknown) =>
              typeof track === 'object' && track !== null && 'languageCode' in track
                ? String((track as { languageCode: unknown }).languageCode)
                : '',
            )
            .filter((code) => code !== '');
          const code = codes.find((c) => c.startsWith('ja')) ?? codes[0];
          if (code !== undefined) player.setOption('captions', 'track', { languageCode: code });
          return;
        }
      } catch {
        // Not ready yet; try again below.
      }
      if (left > 0) window.setTimeout(() => pick(left - 1), 500);
    };
    window.setTimeout(() => pick(6), 400);
  }

  setMuted(muted: boolean): void {
    this.muted = muted;
    if (muted) this.player?.mute();
    else this.player?.unMute();
  }

  isMuted(): boolean {
    return this.muted;
  }
}
