/**
 * A short buzz when a gesture has been understood (operator, 2026-09-24: 決まった瞬間に震える).
 *
 * The gestures leave nothing on screen until they act, and a hand on the glass covers most of
 * what they do show. A buzz answers where the eye cannot: the swipe has gone far enough to go
 * through, the mute has landed, the picture has changed size.
 *
 * Every failure is silent. Not every browser can vibrate, some refuse until the page has been
 * touched, and none of the gestures depend on it.
 */

/** A swipe crossing the point where letting go would put it through. */
export const BUZZ_THRESHOLD_MS = 12;
/** A switch that has flipped: mute, the picture's size. */
export const BUZZ_TOGGLE_MS = 20;
/** One step of a setting that moves in steps: the speed. */
export const BUZZ_STEP_MS = 8;

export function buzz(ms: number): void {
  try {
    navigator.vibrate?.(ms);
  } catch {
    // Nothing to do: the gesture has already done its work.
  }
}
