/**
 * The picker: choose a video out of the operator's own YouTube instead of pasting an address.
 *
 * Typing a video id on a phone is the part of this app that was always tedious. Everything here
 * exists to replace that with tapping. It is strictly additive — the panel starts hidden, and
 * the two players never learn that it exists beyond the one callback that hands them a video id.
 *
 * Rows are built with `textContent`, never `innerHTML`. Titles come from other people's
 * channels, so they are untrusted text that must never be parsed as markup.
 */

import type { GoogleAuth } from '../auth/google.js';
import { clock, uploadAge } from '../core/format.js';
import type { Layout } from '../core/session.js';
import {
  type LibraryItem,
  YouTubeApiError,
  fetchChannelVideos,
  fetchLikedVideos,
  fetchPlaylistItems,
  fetchPlaylists,
  fetchPopularMusic,
  fetchPopularVideos,
  fetchSubscriptions,
  searchVideos,
} from '../youtube/library.js';
import { must } from './dom.js';
import { setIcon } from './icons.js';

/**
 * Where a tapped video goes. The pair screen names its two slots; the wall has twenty, far too
 * many to name on every row, so there it goes to whichever slot is currently chosen. A slot's
 * own 🔍 opens the panel for that slot alone, and then every pick goes there.
 */
export type PickTarget = 'video' | 'music' | 'next' | { readonly slot: number };

/** The slot the panel was opened for, from that slot's own 🔍. */
interface SlotTarget {
  readonly slot: number;
  /** How the slot is named on the buttons: 動画, 音楽, or "7 枠目". */
  readonly label: string;
}

export interface LibraryCallbacks {
  readonly onPick: (videoId: string, target: PickTarget) => void;
  readonly onFillAll: (videoIds: readonly string[]) => void;
  readonly layout: () => Layout;
  /** How many slots are showing — what 上から順に N 枠 can fill without adding any. */
  readonly count: () => number;
  /**
   * Called when a request found that signing in is needed after all.
   *
   * The button outside says 一覧 as long as this device has consented, because a token that
   * expired an hour ago can be replaced without asking anyone. Only a request finding out
   * otherwise can put that right, and only the page outside owns the button.
   */
  readonly onSignInNeeded: () => void;
}

type Tab = 'search' | 'playlists' | 'subscriptions' | 'liked' | 'popular' | 'music';

const TAB_TITLE: Record<Tab, string> = {
  search: '検索',
  playlists: '再生リスト',
  subscriptions: '登録チャンネル',
  liked: '高評価した動画',
  popular: '日本で人気の動画',
  music: '日本で人気の曲',
};

const EMPTY_NOTE: Record<Tab, string> = {
  search: '探したい言葉を入れて「探す」を押す。',
  playlists: '再生リストがありません。',
  subscriptions: '登録しているチャンネルがありません。',
  liked: '高評価した動画がありません。',
  popular: 'いま人気の動画を読み込めませんでした。',
  music: 'いま人気の曲を読み込めませんでした。',
};

function isTab(value: string | undefined): value is Tab {
  return value !== undefined && Object.hasOwn(TAB_TITLE, value);
}

/** Where the panel currently is. A drill-down keeps the tab it came from, for the back button. */
type View =
  | { readonly kind: 'tab'; readonly tab: Tab }
  | { readonly kind: 'playlist'; readonly tab: Tab; readonly item: LibraryItem }
  | { readonly kind: 'channel'; readonly tab: Tab; readonly item: LibraryItem }
  | {
      readonly kind: 'search';
      readonly tab: Tab;
      readonly query: string;
      readonly musicOnly: boolean;
    };

function describeView(view: View): string {
  if (view.kind === 'tab') return TAB_TITLE[view.tab];
  if (view.kind === 'search') return view.musicOnly ? `♪「${view.query}」` : `「${view.query}」`;
  return view.item.title;
}

function describeEmpty(view: View): string {
  if (view.kind === 'tab') return EMPTY_NOTE[view.tab];
  if (view.kind === 'search') return '見つかりませんでした。別の言葉で探してください。';
  return '中身がありません。';
}

/**
 * Whether this failure means the operator has to sign in by hand again.
 *
 * A spent search budget is also a 403 and is not one of these: it will be gone tomorrow, and
 * sending someone to sign in over it teaches them that signing in fixes nothing.
 */
function needsSignIn(error: unknown): boolean {
  if (!(error instanceof YouTubeApiError)) return false;
  if (error.reason === 'quotaExceeded' || error.reason === 'rateLimitExceeded') return false;
  return error.status === 401 || error.status === 403;
}

function describeFailure(error: unknown): string {
  if (error instanceof YouTubeApiError) {
    // A spent search budget and a refused token are both 403. Only the reason tells them apart,
    // and sending someone to sign in again when the answer is "tomorrow" wastes their evening.
    if (error.reason === 'quotaExceeded' || error.reason === 'rateLimitExceeded') {
      return '今日の検索の上限に達しました。日付が変わると戻ります。';
    }
    if (error.status === 401 || error.status === 403) {
      return 'YouTube に断られました。ログインし直してください。';
    }
    return `YouTube が応じません (${error.status})。`;
  }
  return '一覧を取れませんでした。通信を確かめてください。';
}

export class LibraryPanel {
  readonly #panel: HTMLElement;
  readonly #title: HTMLElement;
  readonly #back: HTMLButtonElement;
  readonly #note: HTMLElement;
  readonly #list: HTMLElement;
  readonly #tabs: readonly HTMLButtonElement[];
  readonly #searchRow: HTMLElement;
  readonly #searchInput: HTMLInputElement;
  readonly #auth: GoogleAuth;
  readonly #callbacks: LibraryCallbacks;

  #view: View = { kind: 'tab', tab: 'playlists' };
  /**
   * Set while the panel is working for one slot. Kept across tab changes — someone who opened
   * search for slot 3 and then looked at their playlists still meant slot 3 — and dropped when
   * the panel closes or is opened from the general 一覧 button.
   */
  #slotTarget: SlotTarget | null = null;
  /** Guards against a slow response painting over a list the operator has already left. */
  #requestId = 0;

  constructor(auth: GoogleAuth, callbacks: LibraryCallbacks) {
    this.#auth = auth;
    this.#callbacks = callbacks;

    this.#panel = must<HTMLElement>(document, '#library');
    this.#title = must<HTMLElement>(document, '#libraryTitle');
    this.#back = must<HTMLButtonElement>(document, '#libraryBack');
    this.#note = must<HTMLElement>(document, '#libraryNote');
    this.#list = must<HTMLElement>(document, '#libraryList');
    this.#tabs = [...this.#panel.querySelectorAll<HTMLButtonElement>('[data-tab]')];

    this.#searchRow = must<HTMLElement>(document, '#librarySearchRow');
    this.#searchInput = must<HTMLInputElement>(document, '#librarySearchInput');

    for (const button of this.#tabs) {
      button.addEventListener('click', () => {
        const tab = button.dataset.tab;
        if (isTab(tab)) this.#show({ kind: 'tab', tab });
      });
    }

    /*
     * Songs only: YouTube Music's own catalogue, as far as the API can reach it. Its tracks are
     * ordinary videos filed under the music category, so narrowing a search to that category
     * is how "search YouTube Music" is spelled here. Pressed state is the whole setting.
     */
    const musicToggle = must<HTMLButtonElement>(document, '#librarySearchMusic');
    musicToggle.addEventListener('click', () => {
      const on = musicToggle.getAttribute('aria-pressed') !== 'true';
      musicToggle.setAttribute('aria-pressed', String(on));
    });

    const runSearch = (): void => {
      const query = this.#searchInput.value.trim();
      // An empty search would spend 100 units of the daily budget to find nothing.
      if (query === '') return;
      const musicOnly = musicToggle.getAttribute('aria-pressed') === 'true';
      this.#show({ kind: 'search', tab: 'search', query, musicOnly });
    };
    must<HTMLButtonElement>(document, '#librarySearchGo').addEventListener('click', runSearch);
    this.#searchInput.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') runSearch();
    });

    this.#back.addEventListener('click', () => {
      this.#show({ kind: 'tab', tab: this.#view.tab });
    });
    must<HTMLButtonElement>(document, '#libraryClose').addEventListener('click', () => {
      this.close();
    });
  }

  get isOpen(): boolean {
    return !this.#panel.hidden;
  }

  open(): void {
    this.#slotTarget = null;
    this.#panel.hidden = false;
    this.#show({ kind: 'tab', tab: 'playlists' });
  }

  /**
   * Opens straight onto search, working for one slot (operator, 2026-09-24: 枠ごとに動画を
   * 検索できるようにして). Every video row then offers that slot and nothing else, so the
   * answer to "which slot?" was already given by which 🔍 was pressed.
   */
  openSearchFor(slot: number, label: string): void {
    this.#slotTarget = { slot, label };
    this.#panel.hidden = false;
    this.#show({ kind: 'tab', tab: 'search' });
    this.#searchInput.focus();
  }

  /** Opens a pasted playlist, working for the slot it was pasted into. */
  openPlaylistFor(slot: number, label: string, playlistId: string): void {
    this.#slotTarget = { slot, label };
    this.#panel.hidden = false;
    this.#show({
      kind: 'playlist',
      tab: 'playlists',
      item: { id: playlistId, title: '貼った再生リスト', thumbnail: null },
    });
  }

  close(): void {
    this.#panel.hidden = true;
    this.#slotTarget = null;
    this.#panel.dataset.searchMode = 'false';
  }

  #show(view: View): void {
    this.#view = view;
    this.#panel.dataset.searchMode = String(view.tab === 'search');
    this.#requestId += 1;
    const requestId = this.#requestId;

    this.#back.hidden = view.kind === 'tab';
    this.#title.textContent =
      this.#slotTarget === null
        ? describeView(view)
        : `${describeView(view)} → ${this.#slotTarget.label}`;
    this.#searchRow.hidden = view.tab !== 'search';
    for (const button of this.#tabs) {
      button.setAttribute('aria-pressed', String(button.dataset.tab === view.tab));
    }

    this.#list.replaceChildren();
    this.#note.textContent = '読み込み中…';

    void this.#load(view)
      .then((items) => {
        if (requestId !== this.#requestId) return;
        this.#paint(view, items);
      })
      .catch((error: unknown) => {
        if (requestId !== this.#requestId) return;
        this.#note.textContent = describeFailure(error);
        if (needsSignIn(error)) this.#callbacks.onSignInNeeded();
      });
  }

  async #load(view: View): Promise<LibraryItem[]> {
    // The search tab with nothing typed yet asks YouTube nothing at all — no token, no quota.
    if (view.kind === 'tab' && view.tab === 'search') return [];

    const token = this.#auth.currentToken() ?? (await this.#auth.trySilent());
    if (token === null) {
      // `trySilent` has already dropped the consent note if the refusal was about consent, so
      // a note still standing here means it could not reach Google at all. Calling that
      // "sign in again" would send the operator through a sign-in that fixes nothing.
      if (this.#auth.hasConsented()) throw new Error('silent-unavailable');
      throw new YouTubeApiError(401, 'no token');
    }

    if (view.kind === 'playlist') return fetchPlaylistItems(token, view.item.id);
    if (view.kind === 'channel') return fetchChannelVideos(token, view.item.id);
    if (view.kind === 'search') return searchVideos(token, view.query, view.musicOnly);
    if (view.tab === 'playlists') return fetchPlaylists(token);
    if (view.tab === 'subscriptions') return fetchSubscriptions(token);
    if (view.tab === 'popular') return fetchPopularVideos(token);
    if (view.tab === 'music') return fetchPopularMusic(token);
    return fetchLikedVideos(token);
  }

  /**
   * The 日本で人気 chart without opening the panel, for the 🎲 button outside. The same token
   * path and the same failure words as the tab, so a refusal reads alike wherever it was met.
   * Must start inside a tap, like opening the panel: the token may need a popup.
   */
  async popularVideoIds(): Promise<
    { readonly ids: readonly string[] } | { readonly failure: string }
  > {
    try {
      const items = await this.#load({ kind: 'tab', tab: 'popular' });
      return { ids: items.map((item) => item.id) };
    } catch (error: unknown) {
      if (needsSignIn(error)) this.#callbacks.onSignInNeeded();
      return { failure: describeFailure(error) };
    }
  }

  #paint(view: View, items: LibraryItem[]): void {
    if (items.length === 0) {
      this.#note.textContent = describeEmpty(view);
      return;
    }

    this.#note.textContent = '';
    const holdsVideos =
      view.kind !== 'tab' || view.tab === 'liked' || view.tab === 'popular' || view.tab === 'music';
    const rows = items.map((item) =>
      holdsVideos ? this.#videoRow(item) : this.#folderRow(view, item),
    );
    // Twenty slots filled one tap at a time is twenty taps; this is one. Not while working for
    // one slot: that errand is about one video, and a button that fills twenty would be a trap.
    if (holdsVideos && items.length > 1 && this.#slotTarget === null) {
      rows.unshift(this.#fillAllRow(items));
    }
    this.#list.replaceChildren(...rows);
  }

  /** Pours this list into the wall from the top, opening the wall if it is not showing. */
  #fillAllRow(items: readonly LibraryItem[]): HTMLElement {
    const row = document.createElement('li');
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'library-fill';
    // The slots on screen, not the most there could be (operator, 2026-09-30: 5 枠の時は 5 枠).
    button.textContent = `⬇ 上から順に ${Math.min(items.length, this.#callbacks.count())} 枠へ入れる`;
    button.addEventListener('click', () => {
      this.#callbacks.onFillAll(items.map((item) => item.id));
    });
    row.append(button);
    return row;
  }

  /** A row that opens something: a playlist or a channel. The whole row is the button. */
  #folderRow(view: View, item: LibraryItem): HTMLElement {
    const row = document.createElement('li');
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'library-row';
    button.append(this.#thumbnail(item), this.#label(item.title));
    button.addEventListener('click', () => {
      const kind = view.kind === 'tab' && view.tab === 'subscriptions' ? 'channel' : 'playlist';
      this.#show({ kind, tab: view.tab, item });
    });
    row.append(button);
    return row;
  }

  /** A row that is a video: one tap decides which slot receives it. */
  #videoRow(item: LibraryItem): HTMLElement {
    const row = document.createElement('li');
    const body = document.createElement('div');
    body.className = 'library-row';
    body.append(this.#thumbnail(item), this.#label(item.title, this.#meta(item)));

    const fixed = this.#slotTarget;
    const targets: readonly (readonly [PickTarget, string])[] =
      fixed !== null
        ? [[{ slot: fixed.slot }, `${fixed.label}へ`]]
        : this.#callbacks.layout() === 'wall'
          ? [['next', '選んだ枠へ']]
          : [
              ['video', '動画へ'],
              ['music', '音楽へ'],
            ];

    const actions = document.createElement('div');
    actions.className = 'library-actions';
    for (const [target, label] of targets) {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'icon';
      button.setAttribute('aria-label', label);
      button.title = label;
      const icon =
        target === 'video' || (typeof target === 'object' && target.slot === 0)
          ? 'video'
          : target === 'music' || (typeof target === 'object' && target.slot === 1)
            ? 'music'
            : 'enter';
      setIcon(button, icon);
      button.addEventListener('click', () => {
        this.#callbacks.onPick(item.id, target);
        // The chosen video starts now, so make its picture visible again.
        this.close();
      });
      actions.append(button);
    }

    row.append(body, actions);
    return row;
  }

  /** The picture, with the video's length over its corner the way YouTube shows it. */
  #thumbnail(item: LibraryItem): HTMLElement {
    const frame = document.createElement('span');
    frame.className = 'library-thumb';
    const image = document.createElement('img');
    image.loading = 'lazy';
    image.alt = '';
    if (item.thumbnail !== null) image.src = item.thumbnail;
    frame.append(image);
    const seconds = item.durationSeconds;
    if (typeof seconds === 'number') {
      const badge = document.createElement('span');
      badge.className = 'library-length';
      // A live stream has no length yet; YouTube itself says ライブ there.
      badge.textContent = seconds > 0 ? clock(seconds) : 'ライブ';
      frame.append(badge);
    }
    return frame;
  }

  /** Channel and relative upload age, when known. Empty for playlists and channels. */
  #meta(item: LibraryItem): string {
    return [item.channel ?? '', uploadAge(item.publishedAt)]
      .filter((part) => part !== '')
      .join(' · ');
  }

  #label(title: string, meta = ''): HTMLElement {
    const block = document.createElement('span');
    block.className = 'library-text';
    const span = document.createElement('span');
    span.className = 'library-title';
    // Titles and channel names come from other people's channels; only ever text.
    span.textContent = title;
    block.append(span);
    if (meta !== '') {
      const line = document.createElement('span');
      line.className = 'library-meta';
      line.textContent = meta;
      block.append(line);
    }
    return block;
  }
}
