/**
 * Turning touches on the full-screen picture into commands.
 *
 * The YouTube frame swallows every touch that lands on it, so the gestures live on a
 * transparent sheet laid over the top. That sheet only exists while a slot is full screen;
 * the rest of the time the frame belongs to YouTube, controls and all.
 *
 * All the arithmetic is in `gesture-math.ts` and tested there. What is left here is the
 * bookkeeping that cannot be tested without a browser: which fingers are down, whether a run
 * of taps has finished, and where the current drag started.
 *
 * The map (operator, 2026-09-24, amended 2026-09-30):
 *   one tap             the controls (and, while they are out, play/pause — decided upstream)
 *   two taps            mute, by third: left 動画, right 音楽, middle both
 *   top half, across    move through the video
 *   bottom half, across the speed
 *   left/right, up/down the volume of that third's slot, as for mute
 *   middle, down        leave full screen (up does nothing)
 *   two fingers         spread/squeeze to fill/fit, across to the neighbour
 *
 * Leaving used to be two fingers down, and the middle third's vertical drag moved both
 * volumes at once (operator, 2026-09-30: 真ん中 3 分の 1 上下スワイプで両方の音量調整を
 * 全画面解除に変更・2 本指で全画面解除→廃止). One thumb is enough to get out now.
 *
 * Swipes that move the picture follow the hand and are only decided when it lifts; see
 * `swipeCommits`.
 */

import type { DragKind, Sample, TwoFingerKind, Zone } from './gesture-math.js';
import {
  classifyTwoFinger,
  horizontalJobFor,
  lockedDragKind,
  panAxisFor,
  pinchIntent,
  speedStepsFor,
  swipeCommits,
  swipeGainFor,
  velocityOf,
  zoneOf,
} from './gesture-math.js';

/**
 * How long a tap waits to see whether a second one follows, and so how long a single tap
 * waits before it acts. A double tap is mute (operator, 2026-09-24), so a single tap cannot
 * act at once without every mute also flashing the controls on its way.
 */
const TAP_WINDOW_MS = 320;

export interface GestureHandlers {
  /** A single tap. Acted on once no second tap has followed it. */
  readonly onTap: () => void;
  /** Two taps in quick succession, in this third of the picture: mute. */
  readonly onDoubleTap: (zone: Zone) => void;
  /**
   * A sideways drag in the top half: moving through the video. `dx` is measured from where
   * the finger landed; `done` is set once, when it lifts, and only then should the video jump.
   * A drag abandoned for a two-finger gesture ends with `dx` of 0 and `done` set.
   */
  readonly onScrub: (dx: number, width: number, done: boolean) => void;
  /** A sideways drag in the bottom half, in whole speed steps since the drag began. */
  readonly onSpeedStep: (steps: number) => void;
  /** A vertical drag is about to start in this third: remember where the volumes are now. */
  readonly onVolumeStart: (zone: Zone) => void;
  /**
   * An upward or downward drag, in this third of the picture. `dy` is measured from where the
   * finger landed, so a `dy` of 0 puts everything back where it started.
   */
  readonly onVolume: (zone: Zone, dy: number, height: number) => void;
  /** A squeeze or a spread. */
  readonly onFit: (mode: 'fill' | 'fit') => void;
  /**
   * The picture following the hand. `delta` is how far along the axis from where the swipe
   * began: two fingers across for the neighbour, or one finger down in the middle third to
   * leave. An upward pull is reported too; it is the caller's to ignore.
   */
  readonly onPan: (axis: 'x' | 'y', delta: number) => void;
  /**
   * The hand lifted, or gave up. `commit` says whether the swipe went far or fast enough to
   * go through. Which way counts (only down leaves) is the caller's to say.
   */
  readonly onPanEnd: (axis: 'x' | 'y', delta: number, commit: boolean) => void;
  /**
   * How the picture is sized right now, read when the first finger lands.
   *
   * Needed to undo a squeeze: a third finger means the hand was doing something else, and
   * whatever the two-finger stage changed on the way was never asked for.
   */
  readonly currentFit: () => 'fill' | 'fit';
}

interface Point {
  readonly x: number;
  readonly y: number;
}

function distance(a: Point, b: Point): number {
  return Math.hypot(a.x - b.x, a.y - b.y);
}

/**
 * The middle of however many fingers are down. Two fingers never travel as one, so a swipe
 * has to be measured from what they average out to rather than from either of them.
 */
function centreOf(points: Iterable<Point>): Point {
  let x = 0;
  let y = 0;
  let n = 0;
  for (const point of points) {
    x += point.x;
    y += point.y;
    n += 1;
  }
  return n === 0 ? { x: 0, y: 0 } : { x: x / n, y: y / n };
}

/**
 * Pointer capture keeps a drag alive when the finger wanders off the picture, but it throws
 * for a pointer the browser no longer considers down. Losing capture costs a long drag;
 * letting the error out would cost the gesture entirely.
 */
function capture(sheet: HTMLElement, pointerId: number, hold: boolean): void {
  try {
    if (hold) sheet.setPointerCapture(pointerId);
    else if (sheet.hasPointerCapture(pointerId)) sheet.releasePointerCapture(pointerId);
  } catch {
    // Nothing to do: the gesture still works, it just ends if the finger leaves.
  }
}

/**
 * Starts listening. Returns the function that stops again — the sheet outlives any one
 * full-screen session, so the listeners have to come off with it.
 */
export function attachGestures(sheet: HTMLElement, handlers: GestureHandlers): () => void {
  const active = new Map<number, Point>();

  let startedAt: Point | null = null;
  let lastFingerTime = 0;
  let adjustedX = 0;
  let adjustedY = 0;
  /** Which third the first finger landed in. A drag keeps it however far it wanders. */
  let startZone: Zone = 'centre';
  /** What a sideways drag does, decided by where the finger landed. */
  let horizontalJob: 'scrub' | 'speed' = 'speed';
  let steppedBy = 0;
  /** Whether a scrub has been started and so owes a closing call. */
  let scrubbing = false;
  let dragged = false;
  /** Which way this drag is going, fixed the first time it was clear enough to say. */
  let lockedAxis: DragKind | null = null;
  /** Whether a vertical drag has moved the volume away from where it started. */
  let volumeMoved = false;
  let pinchStart = 0;
  /** Gap at the last fit change, or the widest/narrowest point since it. */
  let pinchAnchor = 0;
  /** Set once two fingers have been down together, so the lift is not read as a tap. */
  let multiTouch = false;
  /** Current mode during this touch, kept separate from its mode at the first finger. */
  let lastFit: 'fill' | 'fit' = 'fit';
  /**
   * Set once three fingers have been down together. Nothing is done with three fingers; the
   * flag is here so a hand that lands three stops doing what its first two fingers started.
   */
  let manyTouch = false;
  /** How the picture was sized before this gesture, so a mistaken squeeze can be put back. */
  let startFit: 'fill' | 'fit' = 'fit';
  /** Where the two fingers averaged out to when the second one landed. */
  let twoFrom: Point | null = null;
  /** What the two fingers are doing, decided once and held until they lift. */
  let twoKind: TwoFingerKind | null = null;
  let panAxis: 'x' | 'y' = 'x';
  let panDelta = 0;
  /** Recent positions of the swipe, for telling a flick from a slow drag. */
  let trail: Sample[] = [];
  /** Set while a swipe is following the hand and so still owes an ending. */
  let panning = false;

  let taps = 0;
  let tapZone: Zone = 'centre';
  let tapTimer: number | null = null;

  const relative = (point: Point): Point => {
    const box = sheet.getBoundingClientRect();
    return { x: point.x - box.left, y: point.y - box.top };
  };

  /**
   * Puts back whatever a one-finger drag changed before a second finger arrived.
   *
   * Two fingers never land at the same instant. In the milliseconds between them the hand is
   * already moving — that is what a squeeze is — so the first finger alone reads as a drag
   * and starts changing the speed, the volume or the position. Without this, every squeeze
   * leaves a stray change behind it.
   */
  const undoOneFingerDrag = (): void => {
    // A one-finger pull out of full screen springs back: two fingers mean something else.
    endPan(true);
    if (steppedBy !== 0) {
      handlers.onSpeedStep(-steppedBy);
      steppedBy = 0;
    }
    if (volumeMoved) {
      handlers.onVolume(startZone, 0, sheet.clientHeight);
      volumeMoved = false;
    }
    if (scrubbing) {
      handlers.onScrub(0, sheet.clientWidth, true);
      scrubbing = false;
    }
    dragged = false;
    lockedAxis = null;
    adjustedX = 0;
    adjustedY = 0;
  };

  const endPan = (giveUp: boolean): void => {
    if (!panning) return;
    panning = false;
    const size = panAxis === 'x' ? sheet.clientWidth : sheet.clientHeight;
    const commit = !giveUp && swipeCommits(panDelta, size, velocityOf(trail));
    handlers.onPanEnd(panAxis, panDelta, commit);
    trail = [];
  };

  const settleTaps = (): void => {
    tapTimer = null;
    const counted = taps;
    taps = 0;
    if (counted === 1) handlers.onTap();
    else if (counted >= 2) handlers.onDoubleTap(tapZone);
  };

  const countTap = (point: Point): void => {
    // The first tap of a run decides the third: a thumb drifts between two quick taps.
    if (taps === 0) tapZone = zoneOf(relative(point).x, sheet.clientWidth);
    taps += 1;
    if (tapTimer !== null) window.clearTimeout(tapTimer);
    // Two is all a run can mean, so there is nothing to wait for after the second.
    if (taps >= 2) settleTaps();
    else tapTimer = window.setTimeout(settleTaps, TAP_WINDOW_MS);
  };

  const onDown = (event: PointerEvent): void => {
    capture(sheet, event.pointerId, true);
    active.set(event.pointerId, { x: event.clientX, y: event.clientY });

    if (active.size === 1) {
      startedAt = { x: event.clientX, y: event.clientY };
      lastFingerTime = event.timeStamp;
      adjustedX = 0;
      adjustedY = 0;
      const at = relative(startedAt);
      startZone = zoneOf(at.x, sheet.clientWidth);
      horizontalJob = horizontalJobFor(at.y, sheet.clientHeight);
      startFit = handlers.currentFit();
      lastFit = startFit;
      steppedBy = 0;
      scrubbing = false;
      dragged = false;
      lockedAxis = null;
      volumeMoved = false;
      multiTouch = false;
      pinchAnchor = 0;
      manyTouch = false;
      twoFrom = null;
      twoKind = null;
      panning = false;
      return;
    }

    multiTouch = true;
    if (active.size === 2) {
      undoOneFingerDrag();
      const [a, b] = [...active.values()];
      pinchStart = a && b ? distance(a, b) : 0;
      pinchAnchor = pinchStart;
      twoFrom = centreOf(active.values());
      twoKind = null;
      trail = [];
      // A run of single taps is not what two fingers meant; drop whatever was counted.
      taps = 0;
      if (tapTimer !== null) {
        window.clearTimeout(tapTimer);
        tapTimer = null;
      }
      return;
    }

    if (active.size === 3 && !manyTouch) {
      manyTouch = true;
      // Whatever the two-finger stage changed on its way here was never asked for.
      endPan(true);
      if (lastFit !== startFit) {
        handlers.onFit(startFit);
        lastFit = startFit;
      }
    }
  };

  const onMove = (event: PointerEvent): void => {
    const previous = active.get(event.pointerId);
    if (previous === undefined) return;
    active.set(event.pointerId, { x: event.clientX, y: event.clientY });

    if (manyTouch) return;

    if (active.size === 2) {
      const [a, b] = [...active.values()];
      if (a === undefined || b === undefined || pinchStart <= 0 || twoFrom === null) return;
      const gap = distance(a, b);
      const centre = centreOf(active.values());
      const dx = centre.x - twoFrom.x;
      const dy = centre.y - twoFrom.y;

      if (twoKind === null) {
        twoKind = classifyTwoFinger(gap - pinchStart, Math.hypot(dx, dy));
        // Only across goes anywhere. Two fingers down used to leave full screen; that moved
        // to one finger in the middle, so a vertical two-finger swipe is held and ignored.
        if (twoKind === 'pan' && panAxisFor(dx, dy) === 'x') {
          panAxis = 'x';
          panning = true;
        }
      }

      if (twoKind === 'pinch') {
        const intent = pinchIntent(gap / pinchAnchor);
        if (intent !== 'none' && intent !== lastFit) {
          lastFit = intent;
          pinchAnchor = gap;
          handlers.onFit(intent);
        } else if (lastFit === 'fill') {
          pinchAnchor = Math.max(pinchAnchor, gap);
        } else {
          pinchAnchor = Math.min(pinchAnchor, gap);
        }
        return;
      }

      if (twoKind === 'pan' && panning) {
        panDelta = panAxis === 'x' ? dx : dy;
        trail.push({ t: event.timeStamp, v: panDelta });
        if (trail.length > 12) trail.shift();
        handlers.onPan(panAxis, panDelta);
      }
      return;
    }

    /*
     * One finger left of two is still part of a two-finger gesture, not the start of a new
     * one-finger drag. Fingers come off one at a time, and the survivor is far from where the
     * first finger landed — so without this it reads as a long drag and throws the speed or
     * the volume across the screen at the exact moment the operator is letting go.
     */
    if (startedAt === null || multiTouch) return;
    const stepX = event.clientX - previous.x;
    const stepY = event.clientY - previous.y;
    const dt = event.timeStamp - lastFingerTime;
    const velocity = dt > 0 ? Math.hypot(stepX, stepY) / dt : Number.NaN;
    const gain = swipeGainFor(velocity);
    adjustedX += stepX * gain;
    adjustedY += stepY * gain;
    lastFingerTime = event.timeStamp;
    const dx = event.clientX - startedAt.x;
    const dy = event.clientY - startedAt.y;
    // Decided once, then held until the hand comes off the glass — see `lockedDragKind`.
    const wasLocked = lockedAxis;
    lockedAxis = lockedDragKind(lockedAxis, dx, dy);
    if (lockedAxis === null) return;
    dragged = true;

    if (lockedAxis === 'horizontal') {
      if (horizontalJob === 'scrub') {
        scrubbing = true;
        handlers.onScrub(adjustedX, sheet.clientWidth, false);
        return;
      }
      const steps = speedStepsFor(adjustedX);
      if (steps !== steppedBy) {
        handlers.onSpeedStep(steps - steppedBy);
        steppedBy = steps;
      }
      return;
    }

    // The middle third, downward: the picture follows the finger out of full screen. Upward
    // does nothing (operator, 2026-09-30: 真ん中スワイプで全画面解除は下だけ).
    if (startZone === 'centre') {
      if (!panning) {
        panning = true;
        panAxis = 'y';
        trail = [];
      }
      panDelta = dy;
      trail.push({ t: event.timeStamp, v: dy });
      if (trail.length > 12) trail.shift();
      handlers.onPan('y', dy);
      return;
    }

    if (wasLocked === null) handlers.onVolumeStart(startZone);
    volumeMoved = true;
    handlers.onVolume(startZone, adjustedY, sheet.clientHeight);
  };

  const onUp = (event: PointerEvent): void => {
    const point = active.get(event.pointerId);
    active.delete(event.pointerId);
    capture(sheet, event.pointerId, false);

    // The swipe is decided the moment the first of its fingers lifts: after that the midpoint
    // is one finger, somewhere else, and would read as a lurch.
    if (active.size < 2) endPan(false);
    if (active.size > 0) return;

    if (scrubbing && startedAt !== null && point !== undefined) {
      handlers.onScrub(adjustedX, sheet.clientWidth, true);
      scrubbing = false;
    }
    if (!dragged && !multiTouch && point !== undefined) countTap(point);
    startedAt = null;
    pinchStart = 0;
    pinchAnchor = 0;
  };

  const onCancel = (event: PointerEvent): void => {
    active.delete(event.pointerId);
    // The browser took a finger away; the picture must not be left half way across.
    if (active.size < 2) endPan(true);
    if (active.size === 0) {
      // The browser took the touch away: whatever the drag had moved stays, but a scrub that
      // never landed must not be left hanging with its preview on screen.
      if (scrubbing) {
        handlers.onScrub(0, sheet.clientWidth, true);
        scrubbing = false;
      }
      startedAt = null;
      pinchStart = 0;
      pinchAnchor = 0;
    }
  };

  sheet.addEventListener('pointerdown', onDown);
  sheet.addEventListener('pointermove', onMove);
  sheet.addEventListener('pointerup', onUp);
  sheet.addEventListener('pointercancel', onCancel);

  return () => {
    sheet.removeEventListener('pointerdown', onDown);
    sheet.removeEventListener('pointermove', onMove);
    sheet.removeEventListener('pointerup', onUp);
    sheet.removeEventListener('pointercancel', onCancel);
    if (tapTimer !== null) window.clearTimeout(tapTimer);
    active.clear();
  };
}
