/**
 * Which build is running, and which one the server is handing out.
 *
 * The app is installed on the tablet as a real app (a TWA), and an installed app has no
 * reload button. It only re-reads the page when Android starts it cold, so picking up a new
 * version meant killing the app from the task switcher every time — which the operator
 * refused to keep doing (2026-09-23). The update button asks the server what it has and
 * compares it with what is running, and this is the comparison.
 *
 * The commit is what decides, not the version number. Two builds of the same version differ
 * whenever anything was changed without a bump, and a version number that went backwards
 * (a revert) is still a change worth taking.
 */

export interface BuildStamp {
  readonly version: string;
  readonly sha: string;
}

/** Never throws: this comes off the network as whatever the server felt like sending. */
export function parseBuildStamp(value: unknown): BuildStamp | null {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return null;

  const record = value as Record<string, unknown>;
  const { version, sha } = record;
  if (typeof version !== 'string' || version.length === 0) return null;
  if (typeof sha !== 'string' || sha.length === 0) return null;

  return { version, sha };
}

/**
 * Whether taking what the server has would change anything.
 *
 * A build whose commit could not be read carries `(unknown)`, and two of those say nothing
 * about each other — offering an update there would be a button that reloads and changes
 * nothing, every single time.
 */
export function isDifferentBuild(running: BuildStamp, served: BuildStamp): boolean {
  if (running.sha === served.sha) return false;
  return isKnownSha(running.sha) && isKnownSha(served.sha);
}

function isKnownSha(sha: string): boolean {
  return /^[0-9a-f]{7,40}$/.test(sha);
}

/**
 * What to say when the app opens on a different build from the one it last ran, or null.
 *
 * An update reaches the app two ways, and only one of them went through the update button:
 * the page is fetched fresh on every load, so whenever Android restarts the app in the
 * background it simply comes back newer, silently (operator, 2026-09-24: 「更新しました」と
 * 出ないけど更新されてる). Comparing against the build seen last time covers both.
 */
export function arrivalNote(previous: BuildStamp | null, running: BuildStamp): string | null {
  if (previous === null || !isDifferentBuild(previous, running)) return null;
  if (previous.version === running.version) return `v${running.version} に更新しました。`;
  return `v${previous.version} から v${running.version} に更新しました。`;
}
