/**
 * Touches over the whole grid, including gestures that start in different video cells.
 *
 * One tap plays or pauses the cell under it. One finger down in the middle third of the
 * screen leaves — the same place and the same move as leaving a single slot's full screen
 * (operator, 2026-09-30: 真ん中スワイプで全画面解除・下だけ・2 本指で全画面解除→廃止).
 * A second finger cancels the touch: nothing here is done with two.
 */

import {
  type Sample,
  TAP_SLOP_PX,
  classifyDrag,
  swipeCommits,
  velocityOf,
  zoneOf,
} from './gesture-math.js';

interface Point {
  readonly x: number;
  readonly y: number;
}

interface Callbacks {
  readonly onTap: (x: number, y: number) => void;
  readonly onExit: () => void;
}

export function attachAllFullGestures(layer: HTMLElement, callbacks: Callbacks): () => void {
  const active = new Map<number, Point>();
  let first: Point | null = null;
  /** Whether the finger landed in the middle third, where a vertical drag leaves. */
  let fromCentre = false;
  let cancelled = false;
  let trail: Sample[] = [];

  const reset = (): void => {
    active.clear();
    first = null;
    fromCentre = false;
    cancelled = false;
    trail = [];
  };

  const onDown = (event: PointerEvent): void => {
    active.set(event.pointerId, { x: event.clientX, y: event.clientY });
    try {
      layer.setPointerCapture(event.pointerId);
    } catch {
      // The layer still receives moves while the finger stays on the screen.
    }
    if (active.size === 1) {
      first = { x: event.clientX, y: event.clientY };
      const box = layer.getBoundingClientRect();
      fromCentre = zoneOf(event.clientX - box.left, layer.clientWidth) === 'centre';
      trail = [{ t: event.timeStamp, v: 0 }];
    } else cancelled = true;
  };

  const onMove = (event: PointerEvent): void => {
    if (!active.has(event.pointerId)) return;
    active.set(event.pointerId, { x: event.clientX, y: event.clientY });
    if (first === null || cancelled) return;
    trail.push({ t: event.timeStamp, v: event.clientY - first.y });
    if (trail.length > 12) trail.shift();
  };

  const onUp = (event: PointerEvent): void => {
    if (!active.has(event.pointerId)) return;
    active.delete(event.pointerId);
    try {
      if (layer.hasPointerCapture(event.pointerId)) layer.releasePointerCapture(event.pointerId);
    } catch {
      // The browser may have released this pointer already.
    }
    if (active.size > 0) return;
    if (!cancelled && first !== null) {
      const dx = event.clientX - first.x;
      const dy = event.clientY - first.y;
      trail.push({ t: event.timeStamp, v: dy });
      if (Math.hypot(dx, dy) <= TAP_SLOP_PX) {
        callbacks.onTap(event.clientX, event.clientY);
      } else if (
        fromCentre &&
        dy > 0 &&
        classifyDrag(dx, dy) === 'vertical' &&
        swipeCommits(dy, layer.clientHeight, velocityOf(trail))
      ) {
        callbacks.onExit();
      }
    }
    reset();
  };

  const onCancel = (event: PointerEvent): void => {
    active.delete(event.pointerId);
    cancelled = true;
    if (active.size === 0) reset();
  };

  layer.addEventListener('pointerdown', onDown);
  layer.addEventListener('pointermove', onMove);
  layer.addEventListener('pointerup', onUp);
  layer.addEventListener('pointercancel', onCancel);
  return () => {
    layer.removeEventListener('pointerdown', onDown);
    layer.removeEventListener('pointermove', onMove);
    layer.removeEventListener('pointerup', onUp);
    layer.removeEventListener('pointercancel', onCancel);
    reset();
  };
}
