/**
 * What the app remembers between visits: which videos were loaded, how loud each was, and how
 * many slots were on screen.
 *
 * The app began as exactly two players — a video plus something playing under it — and two is
 * still the everyday shape. On 2026-09-20 a measurement on the operator's tablet ran 20 at
 * once, none muted and none failing, so the count became the operator's to pick. Since
 * 2026-09-30 it is picked from a fixed list — 1, 2, and then the squares 4, 9, 16, 25 and 36
 * (operator: 1、2、4、9、16、25、36 のいづれかから選ぶ) — so the grid always comes out even.
 * Settings for all thirty-six are kept whatever the screen happens to be showing: turning the
 * count down and back up must not throw away what was already loaded.
 *
 * Stored data is untrusted (the user can edit it, an older version wrote a different shape),
 * so parsing never throws and falls back field by field rather than discarding the whole
 * thing. Both earlier shapes are still read — `{video, music}` from before the wall, and
 * `{layout}` from when the wall was a two-way switch — because the operator's saved slots have
 * to survive every upgrade.
 */

import { NORMAL_SPEED, clampSpeed } from './speed.js';
import { LEGACY_SPLIT_FLOOR, MIN_COLUMNS_FOR_HANDLE, readWidths } from './split.js';
import { parseVideoId } from './video-id.js';
import { clampVolume } from './volume.js';

export const STORAGE_KEY = 'yt-dual.session.v1';

export const PAIR_SLOTS = 2;
export const WALL_COLUMNS = 6;
export const WALL_ROWS = 6;
export const MIN_SLOTS = 1;
export const MAX_SLOTS = WALL_COLUMNS * WALL_ROWS;

/**
 * How many slots make sound: the first is 動画, the second 音楽 (operator, 2026-09-30: 原則
 * 音を鳴らすのは動画、音楽の 2 枠). Every slot after them plays muted, as a shelf of pictures
 * to swap in; tapping one trades it with 動画 or 音楽.
 */
export const SOUND_SLOTS = 2;

/** Whether this slot is one of the two that are heard. */
export function hasSound(index: number): boolean {
  return index >= 0 && index < SOUND_SLOTS;
}

/** The only counts the operator can pick: one, the pair, and then whole squares. */
export const SLOT_COUNTS: readonly number[] = [1, 2, 4, 9, 16, 25, 36];

/** The first slot leads; everything after it plays underneath, so it starts quieter. */
export const DEFAULT_LEAD_VOLUME = 100;
export const DEFAULT_UNDER_VOLUME = 35;

/**
 * Two slots keep the names and the roomy controls the app was built around. Past that the
 * screen is a wall: numbered slots, no address boxes, everything small enough to fit.
 */
export type Layout = 'pair' | 'wall';

export interface SlotSettings {
  readonly videoId: string | null;
  readonly volume: number;
  readonly speed: number;
  /** On by default: a slot that falls silent at the end of its video stops being a slot. */
  readonly loop: boolean;
}

export interface SessionState {
  /** How many slots are on screen, between `MIN_SLOTS` and `MAX_SLOTS`. */
  readonly count: number;
  /** How many stand side by side, or `null` to let the count decide (the usual case). */
  readonly columns: number | null;
  /** Always `MAX_SLOTS` long, however few are showing. */
  readonly slots: readonly SlotSettings[];
  /**
   * How wide each column is, kept separately for each number of columns.
   *
   * A missing entry means "however the grid divides it", which is the usual case. Only counts
   * that actually have a gap to drag are stored, so the smallest key is two.
   */
  readonly widths: Readonly<Record<number, readonly number[]>>;
}

export function defaultVolumeFor(index: number): number {
  return index === 0 ? DEFAULT_LEAD_VOLUME : DEFAULT_UNDER_VOLUME;
}

/**
 * Never throws: a count from storage or a link can be anything at all.
 *
 * A count that is not on the list goes up to the next one that is, so nothing already on
 * screen disappears — a saved 20 from before the list became 25, and a link carrying five
 * videos opens nine slots rather than hiding one of the five.
 */
export function clampCount(value: number): number {
  if (!Number.isFinite(value)) return PAIR_SLOTS;
  const wanted = Math.round(value);
  return SLOT_COUNTS.find((allowed) => allowed >= wanted) ?? MAX_SLOTS;
}

export function layoutFor(count: number): Layout {
  return count > PAIR_SLOTS ? 'wall' : 'pair';
}

/** `null` means "work it out from the count"; a number is the operator's own choice. */
export function clampColumns(value: unknown): number | null {
  if (typeof value !== 'number' || !Number.isFinite(value)) return null;
  const rounded = Math.round(value);
  if (rounded < 1) return null;
  return Math.min(WALL_COLUMNS, rounded);
}

function emptySlots(): SlotSettings[] {
  return Array.from({ length: MAX_SLOTS }, (_unused, index) => ({
    videoId: null,
    volume: defaultVolumeFor(index),
    speed: NORMAL_SPEED,
    loop: true,
  }));
}

export const DEFAULT_SESSION: SessionState = {
  count: PAIR_SLOTS,
  columns: null,
  slots: emptySlots(),
  widths: {},
};

function readRecord(value: unknown): Record<string, unknown> | null {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return null;
  return value as Record<string, unknown>;
}

function readSlot(value: unknown, fallback: SlotSettings): SlotSettings {
  const record = readRecord(value);
  if (record === null) return fallback;

  const rawId = record.videoId;
  const videoId = typeof rawId === 'string' ? parseVideoId(rawId) : null;

  const rawVolume = record.volume;
  const volume = typeof rawVolume === 'number' ? clampVolume(rawVolume) : fallback.volume;

  const rawSpeed = record.speed;
  const speed = typeof rawSpeed === 'number' ? clampSpeed(rawSpeed) : fallback.speed;

  // Anything that is not an explicit `false` loops: that is the default, and a session saved
  // before looping existed carries no opinion about it.
  const loop = record.loop !== false;

  return { videoId, volume, speed, loop };
}

/**
 * Reads all three shapes: `count` is the current one, `layout` was the two-way switch that
 * shipped in v0.7.0, and neither means the slots came from before the wall existed at all.
 */
function readCount(record: Record<string, unknown>): number {
  const stored = record.count;
  if (typeof stored === 'number') return clampCount(stored);
  // The v0.7.0 wall was twenty slots; that is still how many were loaded.
  if (record.layout === 'wall') return clampCount(20);
  return PAIR_SLOTS;
}

/**
 * Reads both shapes. The current one carries `slots`; the one written before the wall existed
 * carried `video` and `music`, which become the first two slots.
 */
function readSlots(record: Record<string, unknown>): SlotSettings[] {
  const slots = emptySlots();
  const stored = record.slots;

  if (Array.isArray(stored)) {
    for (let index = 0; index < MAX_SLOTS; index += 1) {
      slots[index] = readSlot(stored[index], slots[index] as SlotSettings);
    }
    return slots;
  }

  slots[0] = readSlot(record.video, slots[0] as SlotSettings);
  slots[1] = readSlot(record.music, slots[1] as SlotSettings);
  return slots;
}

/**
 * Reads both shapes. The current one carries `widths`, a row of column widths per column
 * count; v0.17 carried `split`, a single number for the two-column case, which becomes the
 * two-column row here. A key that is not a column count the app can draw is dropped rather
 * than repaired — it could only have come from an edit or a later version.
 */
function readAllWidths(record: Record<string, unknown>): Record<number, readonly number[]> {
  const out: Record<number, readonly number[]> = {};

  const stored = readRecord(record.widths);
  if (stored !== null) {
    for (const [key, value] of Object.entries(stored)) {
      const columns = Number(key);
      if (!Number.isInteger(columns)) continue;
      if (columns < MIN_COLUMNS_FOR_HANDLE || columns > WALL_COLUMNS) continue;
      const row = readWidths(value, columns);
      if (row !== null) out[columns] = row;
    }
    return out;
  }

  const split = record.split;
  if (typeof split === 'number' && Number.isFinite(split)) {
    const floor = LEGACY_SPLIT_FLOOR;
    const first = Math.min(1 - floor, Math.max(floor, split));
    out[PAIR_SLOTS] = [first, 1 - first];
  }
  return out;
}

/** Never throws. Anything unreadable becomes the default for that field. */
export function parseSession(raw: string | null | undefined): SessionState {
  if (raw === null || raw === undefined || raw.length === 0) return DEFAULT_SESSION;

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return DEFAULT_SESSION;
  }

  const record = readRecord(parsed);
  if (record === null) return DEFAULT_SESSION;

  return {
    count: readCount(record),
    columns: clampColumns(record.columns),
    slots: readSlots(record),
    widths: readAllWidths(record),
  };
}

export function serializeSession(session: SessionState): string {
  return JSON.stringify(session);
}

/**
 * Let a link carry what to play.
 *
 * `?v=<video>&m=<music>` fills the first two slots, and `?w=<id>,<id>,…` fills the wall from
 * the first slot onward and opens exactly that many. Typing a video id on a phone keyboard
 * is genuinely painful — with a Japanese input method every id arrives as unconverted text
 * that has to be committed by hand — and doing that twenty times is not something anyone
 * would do twice. Volumes are not in the link; those belong to the device, not to the videos.
 *
 * Never throws. An unreadable value leaves that slot as it was.
 */
export function applyLinkOverrides(session: SessionState, search: string): SessionState {
  let params: URLSearchParams;
  try {
    params = new URLSearchParams(search);
  } catch {
    return session;
  }

  const slots = [...session.slots];
  let count = session.count;

  const put = (index: number, raw: string | null): void => {
    if (raw === null || index >= MAX_SLOTS) return;
    const videoId = parseVideoId(raw);
    if (videoId === null) return;
    slots[index] = { ...(slots[index] as SlotSettings), videoId };
    // A slot the link fills but the screen does not show would be a strange answer.
    count = Math.max(count, index + 1);
  };

  const wall = params.get('w');
  if (wall !== null) {
    const ids = wall.split(',').filter((part) => part.length > 0);
    ids.forEach((raw, index) => {
      put(index, raw);
    });
    // The list says how many to open, including when it is shorter than what was saved.
    if (ids.length > 0) count = clampCount(ids.length);
  }

  put(0, params.get('v'));
  put(1, params.get('m'));

  return { ...session, count: clampCount(count), slots };
}
